/**
 * Unit tests for MultiplePiePlot constructor.
 */
public class MultiplePiePlot_MultiplePiePlot_TriageGen2Test {

    @Test
    public void testConstructorWithDataset() {
        // Arrange
        CategoryDataset mockDataset = mock(CategoryDataset.class);

        // Act
        MultiplePiePlot plot = new MultiplePiePlot(mockDataset);

        // Assert
        // Verify dataset assignment
        assertEquals("Dataset should be assigned correctly", mockDataset, plot.getDataset());

        // Verify JFreeChart initialization and properties
        JFreeChart chart = plot.getPieChart();
        assertNotNull("PieChart should not be null", chart);
        assertNull("Background paint should be null", chart.getBackgroundPaint());

        // Verify Legend was removed
        assertFalse("Legend should have been removed", chart.getLegend().isVisible());

        // Verify Title configuration
        TextTitle title = (TextTitle) chart.getTitle();
        assertNotNull("Title should not be null", title);
        assertEquals("Series Title", title.getText());
        assertEquals(Font.SANS_SERIF, title.getFont().getFamily());
        // Note: Font style/size check depends on environment, but we check existence

        // Verify Data Extract Order
        assertEquals("Data extract order should be BY_COLUMN", TableOrder.BY_COLUMN, plot.getDataExtractOrder());

        // Verify Aggregated Items properties
        assertEquals("Aggregated items key should be 'Other'", "Other", plot.getAggregatedItemsKey());
        assertEquals("Aggregated items paint should be light gray", Color.lightGray, plot.getAggregatedItemsPaint());
    }

    @Test
    public void testConstructorWithNullDataset() {
        // Act
        MultiplePiePlot plot = new MultiplePiePlot(null);

        // Assert
        assertNull("Dataset should be null if passed null", plot.getDataset());
        assertNotNull("PieChart should still be initialized even with null dataset", plot.getPieChart());
    }

    @Test
    public void testDefaultConstructor() {
        // Testing the other constructor provided in the signature to ensure coverage of the class
        MultiplePiePlot plot = new MultiplePiePlot();
        assertNull("Default constructor dataset should be null", plot.getDataset());
        assertNotNull("Default constructor should still initialize the chart", plot.getPieChart());
    }
}
